from pathlib import Path
import json,sys,subprocess,hashlib
root=Path(sys.argv[1]); site=root/'site'
def patch(path,old,new):
 p=root/path;s=p.read_text();assert s.count(old)==1,(path,old,s.count(old));p.write_text(s.replace(old,new))
# Names change without changing installed application identity or launch scope.
p=site/'manifest.webmanifest';m=json.loads(p.read_text());m.update(name='Xi Universe',short_name='Xi Universe');p.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n')
