patch('site/hub.js',"let states={},details={},busy=false,workerReady=false,view='discover',refreshGeneration=0;","let states={},details={},busy=false,workerReady=false,view='discover',refreshGeneration=0;\nconst RECENT='xi:ui:recent-v1';let recent=[],collection='all';try{const r=JSON.parse(localStorage.getItem(RECENT)||'[]');if(Array.isArray(r))recent=[...new Set(r.filter(id=>released.some(g=>g.id===id)))].slice(0,6)}catch{}\nconst categories=[['all','Tất cả',g=>true],['strategy','Chiến thuật',g=>/chiến thuật|thủ thành/i.test(g.genre)],['puzzle','Giải đố',g=>/giải đố|xếp khối/i.test(g.genre)],['arcade','Arcade',g=>/kéo ná|vật lý|arcade/i.test(g.genre)],['offline','Offline',g=>!!states[g.id]]];\nfunction recordLaunch(g){recent=[g.id,...recent.filter(id=>id!==g.id)].slice(0,6);try{localStorage.setItem(RECENT,JSON.stringify(recent))}catch{}}\nfunction enterGame(g){recordLaunch(g);location.assign(g.entry)}")
patch('site/hub.js',"if(!['discover','library','settings'].includes(v))return;view=v;for(const id of ['discover','library','settings'])","if(!['discover','library','activity','settings'].includes(v))return;view=v;for(const id of ['discover','library','activity','settings'])")
