patch('site/hub.js',"function render(){",'''function renderLobby(q){
 const spotlight=$('spotlight'),section=$('recentSection');spotlight.hidden=!!q;section.hidden=!!q;
 const chosen=released.find(g=>g.id===recent[0])||released[0];
 if(chosen){const body=e('div','spotlight-body');body.append(e('div','eyebrow',recent.length?'TRỞ LẠI THẾ GIỚI CỦA BẠN':'NỔI BẬT'),e('h3','',chosen.title),e('p','',chosen.subtitle));body.append(btn('Mở '+chosen.title,'primary',()=>launch(chosen),busy||(!states[chosen.id]&&(!navigator.onLine||!workerReady))));spotlight.style.backgroundImage=`url('${chosen.cover}')`;spotlight.replaceChildren(body)}
 const list=$('recentGames');list.replaceChildren();list.classList.toggle('empty',!recent.length);if(!recent.length)list.append(e('p','recent-empty','Trò chơi bạn mở sẽ xuất hiện tại đây.'));else for(const id of recent){const g=released.find(x=>x.id===id);if(!g)continue;const b=btn('', 'recent-tile',()=>launch(g),busy||(!states[id]&&(!navigator.onLine||!workerReady)));const img=e('img');img.src=g.cover;img.alt='';const info=e('span','recent-info');info.append(e('strong','',g.title),e('small','',states[id]?'Sẵn sàng offline':'Mở lại trò chơi'));b.append(img,info);list.append(b)}
 for(const b of $('collections').querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.collection===collection));
 const activity=$('activityGames');activity.replaceChildren(...released.map(g=>{const a=e('article','panel activity-row'),d=details[g.id];a.append(e('h3','',g.title),e('p','',`Phiên bản V${g.version} · ${d?.updateAvailable?'Có bản cập nhật':states[g.id]?'Sẵn sàng offline':'Chưa tải hoặc đang kiểm tra'}`));a.append(btn(d?.updateAvailable?'Quản lý cập nhật':'Quản lý tài nguyên','secondary',()=>select('library')));return a}));
}
for(const [id,label] of categories){const b=btn(label,'collection-chip',()=>{collection=id;render()});b.dataset.collection=id;b.setAttribute('aria-pressed',String(id===collection));$('collections').append(b)}
function render(){''')
