p=site/'hub.css';p.write_text(p.read_text()+'''\n/* Xi lobby: spotlight, recent play, collection filters and activity. */
.spotlight{min-height:220px;isolation:isolate;position:relative;overflow:hidden;border:1px solid var(--line);border-radius:22px;background-color:var(--surface);background-size:cover;background-position:center;display:flex;align-items:end;box-shadow:0 14px 35px #0003}.spotlight::before{content:'';position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,#101014df 0%,#10101482 46%,#10101400 88%),linear-gradient(0deg,#101014bd,transparent 70%)}.spotlight-body{padding:24px;max-width:85%;color:#fff5e6}.spotlight-body .eyebrow{color:#f1d49c;font-size:10px;letter-spacing:1.4px}.spotlight-body h3{font-size:clamp(29px,5vw,49px);color:#fff5e6;margin:9px 0 5px}.spotlight-body p{color:#efe4d4;margin:0 0 15px;font-size:13px}.spotlight-body .primary{min-height:44px;max-width:100%;font-size:13px}.recent-section{margin:25px 0}.recent-games{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(145px,48%);gap:10px;overflow-x:auto;scroll-snap-type:x proximity;padding:2px 2px 8px;scrollbar-width:thin}.recent-games.empty{display:block}.recent-empty{grid-column:1/-1;margin:0;padding:13px 14px;background:var(--surface);border:1px solid var(--line);border-radius:14px;font-size:13px}.recent-tile{padding:0;overflow:hidden;display:flex;flex-direction:column;align-items:stretch;scroll-snap-align:start;text-align:left;background:var(--surface);min-width:0}.recent-tile img{display:block;width:100%;aspect-ratio:16/9;object-fit:cover}.recent-info{padding:9px 10px;display:grid;gap:4px}.recent-info strong{font-size:13px;overflow-wrap:anywhere}.recent-info small{color:var(--muted);font-size:11px}.collections{display:flex;gap:7px;overflow-x:auto;padding:3px 2px 12px;margin:0 0 3px;scrollbar-width:thin}.collection-chip{white-space:nowrap;flex:0 0 auto;padding:9px 13px;font-size:12px;border-radius:999px;min-height:44px}.collection-chip[aria-pressed=true]{background:var(--gold);color:var(--accent-ink);border-color:var(--gold);font-weight:700}.browse-heading{margin-top:26px}.activity-row h3{font-size:22px}.activity-row p{font-size:13px}.shell nav button{min-width:0}.shell nav button span{white-space:nowrap}@media(min-width:750px){.spotlight{min-height:340px}.spotlight-body{padding:34px;max-width:62%}.recent-games{grid-auto-columns:minmax(160px,23%)}}@media(max-width:360px){.shell nav button{font-size:10px;padding-inline:3px}.spotlight-body{padding:19px}.spotlight-body h3{font-size:28px}}
''')
